"""Merge a folder's furniture*.yaml files into furniture.yaml.

Files are merged in name order; when a key appears in more than one file, the
last file wins. Keys match case-insensitively across files.
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Any

import yaml

OUTPUT_NAME = "furniture.yaml"
WARNING = "# DO NOT EDIT THIS FILE DIRECTLY."
HEADER = f"""{WARNING}
# It is generated by room-planner, and any changes will be overwritten.
# Edit the furniture_*.yaml files instead, then run room-planner build or merge.
"""


class UniqueKeyLoader(yaml.SafeLoader):
    """SafeLoader that rejects duplicate keys instead of keeping the last one."""

    def construct_mapping(self, node, deep=False):
        seen = set()
        for key_node, _ in node.value:
            if key_node.tag == "tag:yaml.org,2002:merge":
                continue
            key = self.construct_object(key_node, deep=True)
            if key in seen:
                raise yaml.constructor.ConstructorError(
                    None, None, f"duplicate key: {key!r}", key_node.start_mark
                )
            seen.add(key)
        return super().construct_mapping(node, deep)


def put(target: dict, key: Any, value: Any) -> None:
    """Set target[key], reusing an existing key that differs only by case."""
    folded = str(key).lower()
    key = next((k for k in target if str(k).lower() == folded), key)
    target[key] = value


def find_sources(folder: Path) -> list[Path]:
    """Return the folder's furniture files, except the merged output."""
    return sorted(
        (
            p
            for p in folder.glob("furniture*.yaml")
            if p.is_file() and p.name.lower() != OUTPUT_NAME
        ),
        key=lambda p: p.name.lower(),
    )


def merge(sources: list[Path]) -> dict:
    merged: dict = {"objects": {}}
    for path in sources:
        try:
            # utf-8-sig accepts files with or without a byte order mark.
            content = yaml.load(path.read_text(encoding="utf-8-sig"), UniqueKeyLoader)
        except yaml.YAMLError as exc:
            raise ValueError(f"Could not parse {path}: {exc}") from exc
        if not content:
            continue
        if not isinstance(content, dict):
            raise ValueError(f"{path}: expected a mapping at the top level")

        for key, value in content.items():
            if str(key).lower() != "objects":
                put(merged, key, value)
                continue
            if value is not None and not isinstance(value, dict):
                raise ValueError(f"{path}: 'objects' must be a mapping")
            for name, item in (value or {}).items():
                put(merged["objects"], name, item)

    # Put the metadata (version, units, ...) ahead of the objects.
    merged["objects"] = merged.pop("objects")
    return merged


def merge_folder(folder: Path, *, force: bool = False) -> Path:
    """Merge a folder's furniture files and return the path of the result.

    A furniture.yaml that this program did not generate is never overwritten
    unless force is true, because it may have been written by hand.
    """
    sources = find_sources(folder)
    output = folder / OUTPUT_NAME
    if not sources:
        raise FileNotFoundError(f"No furniture_*.yaml files found in {folder}")
    if output.exists() and not force:
        if not output.read_text(encoding="utf-8-sig").startswith(WARNING):
            raise ValueError(
                f"{output} was not generated by room-planner, so it was not "
                "overwritten. If its contents are also in the furniture_*.yaml "
                "files, run: room-planner merge --force"
            )

    text = HEADER + yaml.safe_dump(merge(sources), sort_keys=False, allow_unicode=True)
    temporary = output.with_name(output.name + ".tmp")
    try:
        temporary.write_text(text, encoding="utf-8", newline="\n")
        os.replace(temporary, output)
    finally:
        temporary.unlink(missing_ok=True)
    return output
